-- Existing quote/manual RPCs only, inside a rolled-back synthetic fixture. No recipient or live approval.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.id(n integer)returns uuid language sql immutable as $$select('d2060003-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.claim(n integer)returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'session_id',pg_temp.id(n+10),'role','authenticated','user_metadata',jsonb_build_object('paid',true,'amount_minor','1','currency','USD','return_url','https://unapproved.example.test'))::text,true)$$;
insert into auth.users(id,email,email_confirmed_at)select pg_temp.id(n),'synthetic-m6-quote-'||n||'@example.test',now()from generate_series(1,2)n;
insert into auth.sessions(id,user_id)select pg_temp.id(n+10),pg_temp.id(n)from generate_series(1,2)n;
insert into public.doctor_candidate_admissions(user_id,purpose,evidence_ref,valid_until)select pg_temp.id(n),'synthetic_fixture','disposable-m6-003:'||n,clock_timestamp()+interval'2 hours'from generate_series(1,2)n;
insert into public.doctor_profiles(user_id,display_name)values(pg_temp.id(1),'Synthetic quote owner'),(pg_temp.id(2),'Synthetic unrelated owner');
insert into public.practices(id,owner_user_id,name)values(pg_temp.id(21),pg_temp.id(1),'Synthetic quote practice'),(pg_temp.id(22),pg_temp.id(2),'Synthetic unrelated practice');
update public.doctor_edition_policy set mode='administrative_candidate',revision=revision+1,change_reason='Explicit synthetic M6-003 verification';
insert into public.doctor_saas_terms_versions(id,plan_key,version,status,currency,currency_exponent,monthly_minor,yearly_minor,trial_days,staff_limit,staff_unlimited,clinic_limit,clinic_unlimited,over_limit_policy,renewal_policy,grace_days,expiry_policy,cancellation_policy,refund_policy,terms_document_ref,commercial_approval_ref,legal_approval_ref)values
(pg_temp.id(51),'synthetic-m6-003',1,'approved','EGP',2,29900,243984,0,4,false,1,false,'block_new_allocation','manual',0,'historical_read_only','period_end','manual_review','synthetic-m6-003/v1','SYNTHETIC_NOT_COMMERCIAL_APPROVAL','SYNTHETIC_NOT_LEGAL_APPROVAL');
insert into public.doctor_saas_terms_documents(terms_version_id,document_ref,content_en,content_ar)values(pg_temp.id(51),'synthetic-m6-003/v1','Synthetic document only; no actual merchant or legal approval.','وثيقة اختبار اصطناعية فقط دون اعتماد تاجر أو قانون.');
update public.doctor_saas_configuration set terms_version_id=pg_temp.id(51),revision=2,change_reason='Disposable quote terms only';
create temporary table results(name text primary key,value jsonb);grant all on results to authenticated;
set local role authenticated;select pg_temp.claim(1);
select is(public.doctor_manual_payment_configuration()->>'selected_route','instapay_manual','existing owner-selected manual direction is retained');
select is(public.doctor_manual_payment_configuration()->>'configured','false','missing actual recipient evidence stays unconfigured');
select is(public.doctor_manual_payment_configuration()->'recipient','null'::jsonb,'no invented recipient or beneficiary');
select is(public.doctor_manual_payment_configuration()->>'live_acceptance_enabled','false','manual direction and published prices do not enable live acceptance');
insert into results values('quote',public.doctor_create_saas_quote(pg_temp.id(51),2,0,'monthly','synthetic-m6-003/v1',pg_temp.id(71)));
select is((select value->>'amount_minor'from results where name='quote'),'29900','server frozen terms defeat browser amount override');
select is((select value->>'currency'from results where name='quote'),'EGP','server frozen currency defeats browser metadata');
select is((select value->>'currency_exponent'from results where name='quote'),'2','precision remains explicit');
select is((select value->>'subscriber_user_id'from results where name='quote'),pg_temp.id(1)::text,'verified actor is the subscriber');
select is((select value->>'practice_id'from results where name='quote'),pg_temp.id(21)::text,'practice comes from stored ownership');
select is(public.doctor_create_saas_quote(pg_temp.id(51),2,0,'monthly','synthetic-m6-003/v1',pg_temp.id(71)),(select value from results where name='quote'),'exact retry returns the unchanged quote');
select throws_ok($$select public.doctor_create_saas_quote(pg_temp.id(51),2,0,'yearly','synthetic-m6-003/v1',pg_temp.id(71))$$,'22023','DOCTOR_IDEMPOTENCY_CONFLICT','same key cannot rewrite interval or amount');
insert into results values('intent',public.doctor_prepare_saas_payment(((select value from results where name='quote')->>'quote_id')::uuid,pg_temp.id(72)));
select is((select value->>'state'from results where name='intent'),'awaiting_route_approval','intent acceptance stays separate from actual route approval');
select is((select value->'quote'from results where name='intent'),(select value from results where name='quote'),'intent preserves the complete frozen quote');
select is((select value#>'{payment_route,checkout_url}'from results where name='intent'),'null'::jsonb,'no browser return URL becomes checkout');
select is((select value#>>'{payment_route,purchase_available}'from results where name='intent'),'false','held quote/intent does not grant purchase authority');
select throws_ok($$select public.doctor_prepare_manual_payment(((select value from results where name='intent')->>'intent_id')::uuid,1,pg_temp.id(73))$$,'DS008','DOCTOR_MANUAL_PAYMENT_UNCONFIGURED','absent actual recipient prevents instructions despite forged metadata');
select is(public.doctor_saas_status()->>'state','unconfigured','quote and intent create no subscription period');
select pg_temp.claim(2);
select throws_ok($$select public.doctor_saas_quote(((select value from results where name='quote')->>'quote_id')::uuid)$$,'42501',null,'other doctor cannot read the frozen subscriber quote');
reset role;
select is((select count(*)::integer from public.doctor_manual_payment_requests),0,'disabled route creates no instruction request');
select is((select count(*)::integer from public.doctor_manual_payment_notices),0,'no customer payment claim is invented');
select is((select count(*)::integer from public.doctor_saas_periods),0,'no trial or paid period is invented');
select ok(not exists(select 1 from doctor_private.command_receipts where command_key=pg_temp.id(73)),'disabled instruction failure leaves no success receipt');
select throws_ok($$update public.doctor_saas_quotes set amount_minor=1 where id=((select value from results where name='quote')->>'quote_id')::uuid$$,'42501','DOCTOR_SAAS_HISTORY_IMMUTABLE','a later mutation cannot rewrite the issued amount');
select ok(not has_table_privilege('authenticated','public.doctor_saas_quotes','SELECT'),'raw quote tables do not bypass scoped server reads');
select * from finish();
rollback;
